def apply_dirs(dirs, scale=1.0, layer_min=0):
    rel = 0.0
    with torch.no_grad():
        for (l, site), d in dirs.items():
            if l < layer_min: continue
            mod = M[name_of[(l, site)]]
            W = mod.weight
            upd = torch.outer(d, d @ W)
            W.data -= scale * upd
