    s += f"Q: {q}\nA:"
    return s

def num(s):
    if not isinstance(s, str): s = str(s)
    m = re.search(r'-?\d+', s)
    return int(m.group()) if m else None

def ask1(q, examples=None):
    try: a = ask([q], examples=examples)
    except TypeError: a = ask(q, examples=examples)
    if isinstance(a, (list, tuple)): a = a[0]
    return a

def probe(qs, exps, examples=None):
    ok = 0; outs = []
    for q, e in zip(qs, exps):
        try: a = ask1(q, examples)
        except Exception: a = None
        outs.append((q, a))
        if num(a) == e: ok += 1
    clean()
    return ok, outs

