def get_resid(ps, bs=8):
    outs = []
    for i in range(0, len(ps), bs):
        with torch.no_grad():
            r = resid(ps[i:i+bs])
        outs.append(r.float().cpu())
        clean()
    return torch.cat(outs, dim=1)

