mean_neu = Rneu.mean(1)
d_add = mean_add - mean_neu
d_sub = mean_sub - mean_neu
L = d_add.shape[0]
dirs = {}
valid = []
for l in range(L):
    da = d_add[l]; ds = d_sub[l]
    ds_norm = ds.norm().item()
    if ds_norm > 1e-6:
        u = ds / ds_norm
        da_perp = da - (da @ u) * u
    else:
        da_perp = da
    norm = da_perp.norm().item()
    if norm > 1e-6:
        dirs[l] = da_perp / norm
        valid.append((l, norm, ds_norm))
    else:
        dirs[l] = None
