def apply_proj(layers, alpha):
    mods = dict(model.named_modules())
    cnt = 0
    with torch.no_grad():
        for l in layers:
            d = dirs.get(l)
            if d is None: continue
            for suffix in ['self_attn.o_proj', 'mlp.down_proj']:
                for name, m in mods.items():
                    if name.endswith(f'layers.{l}.{suffix}') and hasattr(m, 'weight'):
                        W = m.weight
                        dd = d.to(W.device, W.dtype)
                        P = torch.eye(W.shape[0], device=W.device, dtype=W.dtype) - alpha * torch.outer(dd, dd)
                        W.data.copy_(P @ W.data)
                        cnt += 1
    clean()
    return cnt

